#!/usr/bin/env python3
import json, re, html, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
DATA = ROOT / 'constitution_data.json'

with DATA.open(encoding='utf-8') as f:
    data = json.load(f)


def art(n):
    prefix = f'Article {n} '
    for a in data:
        if a.get('heading','').startswith(prefix):
            return a
    raise KeyError(n)


def find(num):
    for a in data:
        for p in a.get('provisions', []):
            if p.get('num') == num:
                return a, p
    raise KeyError(num)


def get(num):
    return find(num)[1]


def setp(num, *, name=None, text=None):
    p = get(num)
    if name is not None: p['name'] = name
    if text is not None: p['text'] = text


def remove(num):
    a, p = find(num)
    a['provisions'].remove(p)
    return p


def insert_after(article, after_num, p):
    ps = article['provisions']
    for i, q in enumerate(ps):
        if q['num'] == after_num:
            ps.insert(i+1, p)
            return
    raise KeyError(after_num)


def add_after(article_num, after_num, num, name, text):
    a = art(article_num)
    # idempotence if rerun
    for q in a['provisions']:
        if q['num'] == num:
            q['name'], q['text'] = name, text
            return
    insert_after(a, after_num, {'num':num,'name':name,'text':text})

# ---------------- Article I ----------------
setp('§1.18', text="Government holds an obligation not to cause environmental harm to persons within its jurisdiction through its own actions or through the actions of those it licenses. The Legislature establishes by statute the framework for environmental protection, and may not enact statutes that systematically permit environmental harm to defined communities. This provision does not require the achievement of any particular environmental outcome; it requires reasonable governmental measures to identify material environmental harms and genuine governmental action toward environmental protection proportionate to harms known or reasonably capable of identification.")

