# -------- synchronize annotated.html constitutional text while preserving page shell/intros --------
ANN = ROOT / 'annotated.html'
if ANN.exists():
    s = ANN.read_text(encoding='utf-8')
    def anchor(num):
        parts = num[1:].split('.')
        out = 's' + parts[0]
        if len(parts)>1: out += '-' + parts[1]
        if len(parts)>2: out += parts[2]
        return out
    def block(p):
        num, name, text = p['num'], p.get('name',''), p.get('text','')
        aid = anchor(num)
        label = (f'  <div class="provision" id="{aid}">\n'
                 f'    <div class="prov-label"><span class="prov-num" title="Click to copy link to {html.escape(num)}" onclick="copyProvLink(\'{aid}\')" style="cursor:pointer">{html.escape(num)}<span class="prov-permalink" aria-hidden="true">¶</span></span><span class="prov-name">{html.escape(name)}</span></div>\n')
        paras = [x.strip() for x in text.split('\n') if x.strip()]
        if len(paras) == 1:
            body = f'    <p class="prov-text">{html.escape(paras[0], quote=False)}</p>\n'
        else:
            body = '    <div class="prov-text">\n' + ''.join(f'      <p class="prov-para">{html.escape(x, quote=False)}</p>\n' for x in paras) + '    </div>\n'
        return label + body + '  </div>\n'
    articles = [a for a in data if not a.get('preamble')]
    starts = list(re.finditer(r'<div id="art(\d+)" class="article-section">', s))
    # Work from end to start so offsets remain valid.
    for m in reversed(starts):
        n = int(m.group(1))
        nxt = next((x for x in starts if x.start() > m.start()), None)
        end = nxt.start() if nxt else s.find('<script', m.start())
        if end < 0: end = len(s)
        section = s[m.start():end]
        a = next((x for x in articles if x['heading'].startswith(f'Article {n} ')), None)
        if not a: continue
        first = section.find('<div class="provision"')
        if first < 0: continue
        prefix = section[:first]
        prefix = re.sub(r'(<h2 class="article-header">)Article [^<]+', lambda z: z.group(1)+html.escape(a['heading']), prefix, count=1)
        newsec = prefix.rstrip() + '\n\n' + '\n'.join(block(p).rstrip() for p in a['provisions']) + '\n</div>\n\n'
        s = s[:m.start()] + newsec + s[end:]
    ANN.write_text(s, encoding='utf-8')

print('Applied constitutional review transformations successfully.')
